  }
  for(const part of (peer?peer[2]:metadata[2]).split('/')){
   assert.ok(part&&part!=='.'&&part!=='..'&&!part.includes('\\'));file=join(file,part);assert.equal(lstatSync(file).isSymbolicLink(),false);
  }
